    inline const char* CategoryLabel(Category c, int lang) noexcept
    {
        switch (c)
        {
        case Category::All: return lang == 1 ? "Все" : (lang == 2 ? "Усі" : "All");
        case Category::Melee: return lang == 1 ? "Ближний" : (lang == 2 ? "Ближній" : "Melee");
        case Category::Pistol: return lang == 1 ? "Пистолеты" : (lang == 2 ? "Пістолети" : "Pistol");
        case Category::SMG: return "SMG";
        case Category::Shotgun: return lang == 1 ? "Дробовики" : (lang == 2 ? "Дробовики" : "Shotgun");
        case Category::Rifle: return lang == 1 ? "Винтовки" : (lang == 2 ? "Гвинтівки" : "Rifle");
        case Category::MG: return "MG";
        case Category::Sniper: return lang == 1 ? "Снайперки" : (lang == 2 ? "Снайперки" : "Sniper");
        case Category::Heavy: return lang == 1 ? "Тяжёлое" : (lang == 2 ? "Важке" : "Heavy");
        case Category::Thrown: return lang == 1 ? "Метательное" : (lang == 2 ? "Метальне" : "Thrown");
        case Category::Other: return lang == 1 ? "Прочее" : (lang == 2 ? "Інше" : "Other");
        default: return "All";
        }
    }

