    inline constexpr int kWeaponCount = static_cast<int>(sizeof(kWeapons) / sizeof(kWeapons[0]));

    inline const Entry* FindByHash(std::uint32_t hash) noexcept
    {
        for (int i = 0; i < kWeaponCount; ++i)
            if (kWeapons[i].hash == hash)
                return &kWeapons[i];
        return nullptr;
    }

    inline const Entry* FindBySpawn(const char* spawn) noexcept
    {
        if (!spawn) return nullptr;
        for (int i = 0; i < kWeaponCount; ++i)
            if (_stricmp(kWeapons[i].spawn, spawn) == 0)
                return &kWeapons[i];
        return nullptr;
    }

    inline WeaponGroups::Group ToAimGroup(Category c) noexcept
    {
        switch (c)
        {
        case Category::Pistol: return WeaponGroups::Group::Pistol;
        case Category::SMG: return WeaponGroups::Group::SMG;
        case Category::Rifle: return WeaponGroups::Group::Rifle;
        case Category::Shotgun: return WeaponGroups::Group::Shotgun;
        case Category::Sniper: return WeaponGroups::Group::Sniper;
        case Category::MG: return WeaponGroups::Group::MG;
        default: return WeaponGroups::Group::General;
        }
    }
